INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (612, 1, 'virtio 가 아닌 NIC', '`/tmp/domiflist.log` 는 `virsh domiflist` 의 출력입니다. 에뮬레이션 NIC(`e1000`, `rtl8139` 등)는 virtio 보다 느립니다. **모델이 `virtio` 가 아닌 인터페이스의 이름**을 이름순으로 한 줄에 하나씩 `/tmp/slow_nics.txt` 에 저장하세요. (이름만)', '표의 앞 두 줄은 제목입니다. 모델 칸을 조건으로 쓰세요.', 'cat /tmp/domiflist.log
awk ''NR>2 && $4!="virtio" {print $1}'' /tmp/domiflist.log | sort > /tmp/slow_nics.txt
cat /tmp/slow_nics.txt

# e1000 같은 에뮬레이션 모델은 실제 하드웨어를 흉내 내느라 호스트 CPU 를 더 쓴다. 게스트에 virtio 드라이버가 있으면 virtio 로 바꾼다(재부팅 필요)', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.xml\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model     MAC\\n-----------------------------------------------------------\\n vnet0       bridge    br0       virtio    52:54:00:aa:00:01\\n vnet1       bridge    br0       e1000     52:54:00:aa:00:02\\n vnet2       network   default   rtl8139   52:54:00:aa:00:03\\nEOF\\ncat > /tmp/ethtool_l.log <<''EOF''\\nChannel parameters for eth0:\\nPre-set maximums:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t4\\nCurrent hardware settings:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t1\\nEOF\\ncat > /tmp/vm_net.xml <<''EOF''\\n    <interface type=''bridge''>\\n      <source bridge=''br0''/>\\n      <model type=''e1000''/>\\n    </interface>\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/slow_nics.txt | xargs)\\" = \\"vnet1 vnet2\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "vnet1, vnet2 이다", "cmd": ["sh", "-c", "[ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/slow_nics.txt | xargs)\\" = \\"vnet1 vnet2\\" ]"]}]', '[{"title": "libvirt NIC 모델과 드라이버", "url": "https://libvirt.org/formatdomain.html#network-interfaces"}, {"title": "ethtool 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (612, 2, '현재 큐 개수 읽기', '`/tmp/ethtool_l.log` 는 게스트에서 본 `ethtool -l eth0` 의 출력입니다. "Pre-set maximums" 는 NIC 가 지원하는 최대 큐 수이고 "Current hardware settings" 는 지금 쓰는 수입니다. **현재 쓰는 Combined 큐 수**를 숫자만 `/tmp/queues.txt` 에 저장하세요.', '`Combined` 줄이 두 번 나옵니다. 어느 쪽이 현재 값인지 구분하세요.', 'cat /tmp/ethtool_l.log
awk ''/Combined/ {v=$2} END {print v}'' /tmp/ethtool_l.log > /tmp/queues.txt
cat /tmp/queues.txt

# 최대 4 인데 1 만 쓰고 있다. vCPU 가 여러 개여도 큐가 1개면 수신 처리가 한 CPU 에 몰린다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.xml\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model     MAC\\n-----------------------------------------------------------\\n vnet0       bridge    br0       virtio    52:54:00:aa:00:01\\n vnet1       bridge    br0       e1000     52:54:00:aa:00:02\\n vnet2       network   default   rtl8139   52:54:00:aa:00:03\\nEOF\\ncat > /tmp/ethtool_l.log <<''EOF''\\nChannel parameters for eth0:\\nPre-set maximums:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t4\\nCurrent hardware settings:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t1\\nEOF\\ncat > /tmp/vm_net.xml <<''EOF''\\n    <interface type=''bridge''>\\n      <source bridge=''br0''/>\\n      <model type=''e1000''/>\\n    </interface>\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(tr -d \\" \\\\n\\" < /tmp/queues.txt)\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "1 이다", "cmd": ["sh", "-c", "[ \\"$(tr -d \\" \\\\n\\" < /tmp/queues.txt)\\" = 1 ]"]}]', '[{"title": "libvirt NIC 모델과 드라이버", "url": "https://libvirt.org/formatdomain.html#network-interfaces"}, {"title": "ethtool 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (612, 3, '게스트의 큐를 늘리는 명령', '게스트 안에서 `eth0` 의 Combined 큐 수를 **4 로 바꾸는** `ethtool` 명령 한 줄을 `/tmp/set_queues.txt` 에 적으세요. (실행하지 않습니다)', '큐(채널) 설정은 ethtool 매뉴얼의 Channel 항목에서 찾아 보세요.', 'echo ''ethtool -L eth0 combined 4'' > /tmp/set_queues.txt
cat /tmp/set_queues.txt

# 호스트에서 VM 의 NIC 에 queues 를 지정해 둬야 4 까지 올릴 수 있다. 재부팅하면 풀리므로 영구 설정은 네트워크 설정 파일에 넣는다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.xml\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model     MAC\\n-----------------------------------------------------------\\n vnet0       bridge    br0       virtio    52:54:00:aa:00:01\\n vnet1       bridge    br0       e1000     52:54:00:aa:00:02\\n vnet2       network   default   rtl8139   52:54:00:aa:00:03\\nEOF\\ncat > /tmp/ethtool_l.log <<''EOF''\\nChannel parameters for eth0:\\nPre-set maximums:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t4\\nCurrent hardware settings:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t1\\nEOF\\ncat > /tmp/vm_net.xml <<''EOF''\\n    <interface type=''bridge''>\\n      <source bridge=''br0''/>\\n      <model type=''e1000''/>\\n    </interface>\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"^[[:space:]]*(sudo )?ethtool( --set-channels| -L) eth0 combined 4[[:space:]]*$\\" /tmp/set_queues.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ethtool -L 로 eth0 combined 4", "cmd": ["sh", "-c", "grep -Eq \\"^[[:space:]]*(sudo )?ethtool( --set-channels| -L) eth0 combined 4[[:space:]]*$\\" /tmp/set_queues.txt"]}]', '[{"title": "libvirt NIC 모델과 드라이버", "url": "https://libvirt.org/formatdomain.html#network-interfaces"}, {"title": "ethtool 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (612, 4, 'NIC XML 을 virtio·멀티큐로', '`/tmp/vm_net.xml` 의 NIC 는 지금 에뮬레이션 모델입니다. **모델을 `virtio` 로 바꾸고**, `<model>` 줄 바로 아래에 **호스트 커널에서 패킷을 처리(vhost)하며 큐를 4개 쓰는** `<driver>` 요소를 추가하세요.', '`driver` 요소에는 이름과 큐 수 속성이 있습니다. 이름은 호스트 커널에서 패킷을 처리하는 모듈과 관련됩니다.', 'sed -i "s:<model type=''e1000''/>:<model type=''virtio''/>:" /tmp/vm_net.xml
sed -i "/<model type=''virtio''\\/>/a\\\\      <driver name=''vhost'' queues=''4''/>" /tmp/vm_net.xml
cat /tmp/vm_net.xml

# queues 를 쓰려면 모델이 virtio 여야 한다. 게스트는 ethtool -L 로 큐를 늘려야 실제로 쓴다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.xml\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model     MAC\\n-----------------------------------------------------------\\n vnet0       bridge    br0       virtio    52:54:00:aa:00:01\\n vnet1       bridge    br0       e1000     52:54:00:aa:00:02\\n vnet2       network   default   rtl8139   52:54:00:aa:00:03\\nEOF\\ncat > /tmp/ethtool_l.log <<''EOF''\\nChannel parameters for eth0:\\nPre-set maximums:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t4\\nCurrent hardware settings:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t1\\nEOF\\ncat > /tmp/vm_net.xml <<''EOF''\\n    <interface type=''bridge''>\\n      <source bridge=''br0''/>\\n      <model type=''e1000''/>\\n    </interface>\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"<model type=.virtio.\\\\s*/>\\" /tmp/vm_net.xml ) && ( ! grep -q e1000 /tmp/vm_net.xml ) && ( grep -v ''<!--'' /tmp/vm_net.xml | grep -E ''<driver'' | grep -E \\"name=[''\\\\\\"]vhost[''\\\\\\"]\\" | grep -Eq \\"queues=[''\\\\\\"]4[''\\\\\\"]\\" ) && ( [ \\"$(grep -n \\"<driver\\" /tmp/vm_net.xml | head -1 | cut -d: -f1)\\" -gt \\"$(grep -n \\"<model\\" /tmp/vm_net.xml | head -1 | cut -d: -f1)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "모델이 virtio 다", "cmd": ["sh", "-c", "grep -Eq \\"<model type=.virtio.\\\\s*/>\\" /tmp/vm_net.xml"]}, {"label": "e1000 이 남지 않았다", "cmd": ["sh", "-c", "! grep -q e1000 /tmp/vm_net.xml"]}, {"label": "driver 가 vhost, 큐 4 다", "cmd": ["sh", "-c", "grep -v ''<!--'' /tmp/vm_net.xml | grep -E ''<driver'' | grep -E \\"name=[''\\\\\\"]vhost[''\\\\\\"]\\" | grep -Eq \\"queues=[''\\\\\\"]4[''\\\\\\"]\\""]}, {"label": "driver 가 model 뒤에 있다", "cmd": ["sh", "-c", "[ \\"$(grep -n \\"<driver\\" /tmp/vm_net.xml | head -1 | cut -d: -f1)\\" -gt \\"$(grep -n \\"<model\\" /tmp/vm_net.xml | head -1 | cut -d: -f1)\\" ]"]}]', '[{"title": "libvirt NIC 모델과 드라이버", "url": "https://libvirt.org/formatdomain.html#network-interfaces"}, {"title": "ethtool 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (612, 5, 'vhost-net 확인', '호스트에서 커널 모듈 `vhost_net` 이 **올라와 있는지** 확인하는 명령 한 줄을 `/tmp/vhost_check.txt` 에 적으세요. (모듈 목록을 보는 명령과 이름 검색)', '모듈 목록을 보는 명령의 출력을 걸러 이름을 찾으세요.', 'echo ''lsmod | grep vhost_net'' > /tmp/vhost_check.txt
cat /tmp/vhost_check.txt

# 출력이 없으면 modprobe vhost_net 으로 올린다. /dev/vhost-net 장치가 있어야 libvirt 가 vhost 를 쓴다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log /tmp/*.xml\\ncat > /tmp/domiflist.log <<''EOF''\\n Interface   Type      Source    Model     MAC\\n-----------------------------------------------------------\\n vnet0       bridge    br0       virtio    52:54:00:aa:00:01\\n vnet1       bridge    br0       e1000     52:54:00:aa:00:02\\n vnet2       network   default   rtl8139   52:54:00:aa:00:03\\nEOF\\ncat > /tmp/ethtool_l.log <<''EOF''\\nChannel parameters for eth0:\\nPre-set maximums:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t4\\nCurrent hardware settings:\\nRX:\\t\\tn/a\\nTX:\\t\\tn/a\\nOther:\\t\\tn/a\\nCombined:\\t1\\nEOF\\ncat > /tmp/vm_net.xml <<''EOF''\\n    <interface type=''bridge''>\\n      <source bridge=''br0''/>\\n      <model type=''e1000''/>\\n    </interface>\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"(lsmod|/proc/modules)\\" /tmp/vhost_check.txt && grep -Eq \\"vhost_net\\" /tmp/vhost_check.txt && ! grep -Eq \\"grep[^|]* -[a-zA-Z]*[vc]\\" /tmp/vhost_check.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "모듈 목록에서 vhost_net 을 찾는다", "cmd": ["sh", "-c", "grep -Eq \\"(lsmod|/proc/modules)\\" /tmp/vhost_check.txt && grep -Eq \\"vhost_net\\" /tmp/vhost_check.txt && ! grep -Eq \\"grep[^|]* -[a-zA-Z]*[vc]\\" /tmp/vhost_check.txt"]}]', '[{"title": "libvirt NIC 모델과 드라이버", "url": "https://libvirt.org/formatdomain.html#network-interfaces"}, {"title": "ethtool 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (612, 6, 'e1000 와 virtio', 'VM 의 NIC 모델을 `e1000` 에서 `virtio` 로 바꾸면 보통 어떤 변화가 있나요?', '에뮬레이션은 실제 장치를 흉내 내느라 일을 더 합니다.', NULL, NULL, '[]', 'choice', '["성능은 같고 게스트에서 보이는 장치 이름만 달라질 뿐이다", "처리량은 늘지만 게스트 OS 를 반드시 새로 설치해야만 한다", "호스트 CPU 사용이 줄고 처리량이 늘지만 게스트에 드라이버가 필요하다", "지연은 줄지만 라이브 마이그레이션이 더는 불가능해진다"]', 2, 'virtio 는 가상화에 맞춘 반가상화 장치라 에뮬레이션보다 오버헤드가 작습니다. 최신 리눅스 커널은 드라이버를 기본 포함하고 Windows 는 별도 드라이버가 필요합니다. 마이그레이션은 virtio 로도 문제없이 됩니다.', NULL, NULL, NULL, NULL),
  (612, 7, '멀티큐가 도움이 되는 경우', '멀티큐(`queues=4`) 설정이 가장 효과가 큰 상황은?', '큐가 여러 개면 수신 처리를 여러 CPU 가 나눠 맡습니다.', NULL, NULL, '[]', 'choice', '["vCPU 1개로 가끔 SSH 접속만 하는 정도로 쓰는 VM", "vCPU 가 여러 개이고 패킷이 많은 서비스를 도는 VM", "디스크 입출력이 많고 네트워크는 거의 쓰지 않는 VM", "네트워크 장치가 전혀 연결되지 않은 상태의 VM"]', 1, '멀티큐는 패킷 처리를 여러 vCPU 로 분산해 처리량이 높은 VM 에서 효과가 큽니다. vCPU 가 하나거나 트래픽이 적으면 이득이 거의 없고, 큐 수는 vCPU 수를 넘기지 않는 것이 일반적입니다.', NULL, NULL, NULL, NULL),
  (612, 8, 'vhost-net', 'vhost-net 을 쓰면 패킷 처리 경로가 어떻게 달라지나요?', '처리 위치가 사용자 공간 프로세스에서 어디로 옮겨 가는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["QEMU 프로세스 대신 호스트 커널이 처리해 컨텍스트 전환이 줄어든다", "게스트 커널이 호스트 대신 물리 NIC 를 직접 구동한다", "패킷을 모두 디스크에 먼저 기록한 뒤 전달한다", "브리지를 거치지 않고 NIC 를 독점한다"]', 0, 'vhost-net 은 virtio 패킷 처리를 QEMU 사용자 공간에서 호스트 커널 스레드로 옮겨 컨텍스트 전환과 복사를 줄입니다. 물리 NIC 를 독점하는 것은 SR-IOV·패스스루입니다.', NULL, NULL, NULL, NULL),
  (612, 9, '큐 개수 바꾸기', '게스트에서 NIC 의 큐(채널) 개수를 **바꾸는** `ethtool` 옵션을 채우세요. (대소문자를 구분합니다)', '조회 옵션과 설정 옵션은 서로 다른 글자입니다.', NULL, NULL, '[]', 'fill', '["L", "l", "g", "i"]', NULL, '`-L`(`--set-channels`)은 채널 수를 바꾸고 `-l` 은 조회합니다. `-g` 는 링 버퍼, `-i` 는 드라이버 정보를 봅니다.', '[0]', 'ethtool -{0} eth0 combined 4', NULL, NULL),
  (612, 10, '패킷이 지나는 길', '브리지 네트워크의 VM 이 외부로 패킷을 보낼 때 지나는 길입니다. 올바른 순서로 놓으세요.', '패킷이 가상 영역에서 물리 영역으로 나갑니다.', NULL, NULL, '[]', 'order', '["호스트의 브리지", "게스트 안의 virtio 드라이버", "호스트의 물리 NIC", "호스트의 tap 장치(vnet)"]', NULL, '게스트의 virtio 드라이버에서 출발한 패킷은 호스트의 tap 장치(vnetX)로 넘어오고, 브리지가 이를 전달해 물리 NIC 로 나갑니다.', '[1, 3, 0, 2]', NULL, NULL, NULL);
